import{_ as o,c as a,o as n,ag as t}from"./chunks/framework.Vyheyqg9.js";const _=JSON.parse('{"title":"Practice: How would you onboard new people on a project? What kind of documentation/style guide would you use?","description":"","frontmatter":{},"headers":[],"relativePath":"practice/engineering/design/How_would_you_onboard_new_people_on_a_project,_What_kind_of_documentation,_style_guide_would_you_use.md","filePath":"practice/engineering/design/How_would_you_onboard_new_people_on_a_project,_What_kind_of_documentation,_style_guide_would_you_use.md"}'),r={name:"practice/engineering/design/How_would_you_onboard_new_people_on_a_project,_What_kind_of_documentation,_style_guide_would_you_use.md"};function i(s,e,c,d,u,l){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="practice-how-would-you-onboard-new-people-on-a-project-what-kind-of-documentation-style-guide-would-you-use" tabindex="-1">Practice: How would you onboard new people on a project? What kind of documentation/style guide would you use? <a class="header-anchor" href="#practice-how-would-you-onboard-new-people-on-a-project-what-kind-of-documentation-style-guide-would-you-use" aria-label="Permalink to “Practice: How would you onboard new people on a project? What kind of documentation/style guide would you use?”">​</a></h1><p><strong>Learner status: outstanding.</strong> Author verification does not complete these criteria.</p><p>Prerequisite: <a href="./../../../senior_growth/EngX_Quality/How_would_you_onboard_new_people_on_a_project%2C_What_kind_of_documentation%2C_style_guide_would_you_use.html">the worked lesson</a> and <a href="./../">the shared sequence</a>. Reuse the mapped existing project rather than build an application per note.</p><h2 id="scope-observable-acceptance-and-failure-cases" tabindex="-1"><span class="hub-section-number">1 </span>Scope, observable acceptance and failure cases <a class="header-anchor" href="#scope-observable-acceptance-and-failure-cases" aria-label="Permalink to “1 Scope, observable acceptance and failure cases”">​</a></h2><p><strong>Onboarding exercise:</strong> locate the UI → application port → adapter path, explain who constructs the adapter and run both positive and negative boundary cases. Propose one justified exception, record the risk/owner/expiry and explain whether the rule or architecture should change. Then trace the title helper&#39;s <a href="./../../../senior_growth/EngX_Quality/How_would_you_approach_significant_refactoring.html#estimate-uncertainty-and-make-the-debt-decision-reviewable">incremental migration and estimate</a>. Acceptance: a new reader can identify the decision, alternatives, forces, consequences, current status, evidence and revisit trigger without relying on undocumented chat history. The record is worked learning material; actual teammate onboarding, decision adoption and measured communication outcomes remain learner practice.</p><p><strong>Practice acceptance:</strong> add an error/retry parent that always clears Busy in <code>finally</code>, preserves an accessible error message, and does not execute two writes. Add Ready/Disabled/Busy examples with long translated labels. Record Enter/Space, focus, screen-reader busy announcement and zoom observations in a browser. Propose a breaking prop rename and show both old and migrated consumers plus a version/changelog decision. Material completion is distinct from these still-required observations.</p><p><strong>Practice acceptance:</strong> ask a real reviewer to reproduce the failure from the retained setup, submit a scoped local correction, map acceptance to actual checks, and record what the reviewer misunderstood and what documentation changed. Retain before/after results, unresolved risks and a follow-up receipt. Do not invent a reviewer, claim the example dialogue happened, or mark mentoring/stakeholder outcomes complete from authored prose. Actual human participation and measured onboarding effectiveness remain learner evidence.</p><h2 id="evidence" tabindex="-1"><span class="hub-section-number">2 </span>Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to “2 Evidence”">​</a></h2><p>Record source/runtime/tool versions, prerequisites and input, expected versus actual behavior, at least one failure→fix→retest, commands/exit status and retained artifacts. Distinguish local/mocked/source checks from native browser, external-service and deployment results. Screen-reader, zoom, real-device and cross-engine checks remain open unless actually performed. No remote push or paid-service activation.</p>',9)])])}const h=o(r,[["render",i]]);export{_ as __pageData,h as default};
